window.ARB_DOCS["choice_sets"]={"reasons_bankrot_gr":{"label":"Основание признания гражданина банкротом","options":[{"value":"plan_requirements","label":"Не соответствует требованиям для утверждения плана","text":"гражданин не соответствует требованиям для утверждения плана реструктуризации долгов (п. 1 ст. 213.13, п. 8 ст. 213.6 127-ФЗ)","norm":"п. 1 ст. 213.13, п. 8 ст. 213.6 127-ФЗ"},{"value":"income_insufficient","label":"Дохода недостаточно для погашения в пределах трёх лет","text":"дохода гражданина недостаточно для погашения требований кредиторов в срок, не превышающий трёх лет (п. 2 ст. 213.14 127-ФЗ)","norm":"п. 2 ст. 213.14 127-ФЗ"},{"value":"plan_not_submitted","label":"План не представлен в срок","text":"план реструктуризации долгов не представлен в установленный срок (п. 1 ст. 213.24 127-ФЗ)","norm":"п. 1 ст. 213.24 127-ФЗ"},{"value":"meeting_rejected","label":"Собрание не одобрило план / решило обратиться в суд","text":"собрание кредиторов {{ДАТА_СОБРАНИЯ}} не одобрило план реструктуризации долгов и приняло решение обратиться в арбитражный суд с ходатайством о признании гражданина банкротом (п. 1 ст. 213.24, ст. 213.17 127-ФЗ)","norm":"п. 1 ст. 213.24, ст. 213.17 127-ФЗ","fields":["ДАТА_СОБРАНИЯ"]},{"value":"plan_cancelled","label":"План отменён","text":"план реструктуризации долгов отменён арбитражным судом (п. 1 ст. 213.24, ст. 213.23 127-ФЗ)","norm":"п. 1 ст. 213.24, ст. 213.23 127-ФЗ"},{"value":"debtor_petition","label":"Ходатайство гражданина","text":"гражданин ходатайствует о признании его банкротом и введении процедуры реализации имущества (п. 1 ст. 213.24, п. 8 ст. 213.6 127-ФЗ)","norm":"п. 1 ст. 213.24, п. 8 ст. 213.6 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"reasons_bankrot_gr","allow_custom":true},"grounds_zavershenie_gr":{"label":"Основание завершения реализации имущества","options":[{"value":"completed","label":"Мероприятия выполнены, имущество реализовано","text":"все мероприятия процедуры реализации имущества выполнены, выявленное имущество реализовано, вырученные средства распределены между кредиторами","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"no_estate","label":"Конкурсной массы нет","text":"конкурсная масса не сформирована: имущество, подлежащее реализации, не выявлено, дальнейшее проведение мероприятий не приведёт к поступлению средств","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"fully_paid","label":"Требования погашены полностью","text":"требования кредиторов, включённые в реестр, погашены в полном объёме","norm":"п. 1 ст. 213.28 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"grounds_zavershenie_gr","allow_custom":true},"discharge_gr":{"label":"Освобождение от обязательств","default":"apply","options":[{"value":"apply","label":"Применить освобождение (по умолчанию)","text":"Применить в отношении гражданина правила об освобождении от исполнения обязательств (п. 3 ст. 213.28 127-ФЗ); обстоятельства, предусмотренные п. 4 ст. 213.28 127-ФЗ, не выявлены","norm":"п. 3, 4 ст. 213.28 127-ФЗ","default":true},{"value":"deny_illegal","label":"Не применять: незаконные действия при возникновении или исполнении обязательства","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: при возникновении или исполнении обязательства гражданин действовал незаконно (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_info","label":"Не применять: непредоставление или искажение сведений","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин не предоставил необходимые сведения или предоставил заведомо недостоверные сведения финансовому управляющему или арбитражному суду (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_concealment","label":"Не применять: сокрытие или уничтожение имущества","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин скрыл или умышленно уничтожил имущество (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"deny_liability","label":"Не применять: привлечение к ответственности, преднамеренное или фиктивное банкротство","text":"Не применять в отношении гражданина правила об освобождении от исполнения обязательств: гражданин привлечён к уголовной или административной ответственности за неправомерные действия при банкротстве, преднамеренное или фиктивное банкротство (п. 4 ст. 213.28 127-ФЗ)","norm":"п. 4 ст. 213.28 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"discharge_gr","allow_custom":true},"conclusion_prednamerennoe":{"label":"Вывод о признаках преднамеренного банкротства","prefill_from":"finanalysis","options":[{"value":"found","label":"выявлены","text":"признаки преднамеренного банкротства выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"not_found","label":"не выявлены","text":"признаки преднамеренного банкротства не выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"impossible","label":"проверка невозможна","text":"провести проверку наличия (отсутствия) признаков преднамеренного банкротства невозможно в связи с отсутствием документов, необходимых для проведения проверки (пп. «в» п. 10 Временных правил, утв. постановлением Правительства РФ от 27.12.2004 № 855)","norm":"пп. «в» п. 10 Временных правил проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855","norm_short":"пп. «в» п. 10 ПП № 855","autofill":false},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_prednamerennoe","allow_custom":true},"conclusion_fiktivnoe":{"label":"Вывод о признаках фиктивного банкротства","prefill_from":"finanalysis","options":[{"value":"found","label":"выявлены","text":"признаки фиктивного банкротства выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"not_found","label":"не выявлены","text":"признаки фиктивного банкротства не выявлены","norm":"Временные правила проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855"},{"value":"not_applicable","label":"не проверялись","text":"определение признаков фиктивного банкротства не производилось, поскольку производство по делу о банкротстве возбуждено не по заявлению должника (п. 11 Временных правил проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855)","norm":"п. 11 Временных правил проверки арбитражным управляющим наличия признаков фиктивного и преднамеренного банкротства, утв. постановлением Правительства РФ от 27.12.2004 № 855","norm_short":"п. 11 ПП № 855","ui":{"style":"neutral","color":"grey","chip":true,"is_finding":false,"note":"не вывод о признаках: проверку не проводили (дело возбуждено не по заявлению должника)"}},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_fiktivnoe","allow_custom":true},"conclusion_sdelki":{"label":"Вывод об основаниях для оспаривания сделок","prefill_from":"finanalysis","options":[{"value":"exist","label":"есть","text":"выявлены сделки, имеющие признаки недействительности по ст. 61.2, 61.3 127-ФЗ; основания для их оспаривания имеются","norm":"ст. 61.2, 61.3 127-ФЗ"},{"value":"absent","label":"отсутствуют","text":"основания для оспаривания сделок должника по ст. 61.2, 61.3 127-ФЗ отсутствуют","norm":"ст. 61.2, 61.3 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_sdelki","allow_custom":true},"conclusion_sufficiency":{"label":"Вывод о достаточности имущества","prefill_from":"finanalysis","options":[{"value":"sufficient","label":"достаточно","text":"имущества должника достаточно для покрытия судебных расходов и расходов на выплату вознаграждения арбитражному управляющему","norm":"ст. 20.6, 59 127-ФЗ; Правила проведения арбитражным управляющим финансового анализа, утв. постановлением Правительства РФ от 25.06.2003 № 367"},{"value":"insufficient","label":"недостаточно","text":"имущества должника недостаточно для покрытия судебных расходов и расходов на выплату вознаграждения арбитражному управляющему","norm":"ст. 20.6, 59 127-ФЗ; Правила проведения арбитражным управляющим финансового анализа, утв. постановлением Правительства РФ от 25.06.2003 № 367"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"conclusion_sufficiency","allow_custom":true},"control_grounds_6110":{"label":"Основание отнесения ответчика к КДЛ","multiple":true,"source":"documents/control_grounds.json (Судебная практика)","edition_checked":"Гарант, действующая редакция на 16.10.2026; ПП ВС № 53 — с изм. ПП ВС от 23.12.2025 № 42","options":[{"value":"p2_1_rodstvo","label":"Родство/свойство с руководством или должностное положение","text":"ответчик имел возможность определять действия должника в силу нахождения с должником (руководителем или членами органов управления должника) в отношениях родства или свойства либо в силу должностного положения (пп. 1 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 1 п. 2 ст. 61.10 127-ФЗ","quote":"1) в силу нахождения с должником (руководителем или членами органов управления должника) в отношениях родства или свойства, должностного положения;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_2_doverennost","label":"Полномочия на сделки по доверенности или спецполномочию","text":"ответчик имел возможность определять действия должника в силу наличия полномочий совершать сделки от имени должника, основанных на доверенности, нормативном правовом акте либо ином специальном полномочии (пп. 2 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 2 п. 2 ст. 61.10 127-ФЗ","quote":"2) в силу наличия полномочий совершать сделки от имени должника, основанных на доверенности, нормативном правовом акте либо ином специальном полномочии;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_3_dolzhnost","label":"Должность: главбух, финдиректор и т.п.","text":"ответчик имел возможность определять действия должника в силу должностного положения (замещал должность главного бухгалтера, финансового директора должника либо иную должность, предоставляющую возможность определять действия должника) (пп. 3 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 3 п. 2 ст. 61.10 127-ФЗ","quote":"3) в силу должностного положения (в частности, замещения должности главного бухгалтера, финансового директора должника либо лиц, указанных в подпункте 2 пункта 4 настоящей статьи, а также иной должности, предоставляющей возможность определять действия должника);","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p2_4_inoe_vliyanie","label":"Принуждение или определяющее влияние на руководство","text":"ответчик имел возможность определять действия должника иным образом, в том числе путём принуждения руководителя или членов органов управления должника либо оказания на них определяющего влияния (пп. 4 п. 2 ст. 61.10 Закона о банкротстве)","norm":"пп. 4 п. 2 ст. 61.10 127-ФЗ","quote":"4) иным образом, в том числе путем принуждения руководителя или членов органов управления должника либо оказания определяющего влияния на руководителя или членов органов управления должника иным образом.","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 2 ст. 61.10 — способы контроля"},{"value":"p4_1_rukovoditel","label":"Презумпция: руководитель, член исп. органа, ликвидатор","text":"ответчик являлся руководителем должника (управляющей организации должника, членом исполнительного органа должника, ликвидатором должника, членом ликвидационной комиссии) и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 1 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 1 п. 4 ст. 61.10 127-ФЗ","quote":"Пока не доказано иное, предполагается, что лицо являлось контролирующим должника лицом, если это лицо: 1) являлось руководителем должника или управляющей организации должника, членом исполнительного органа должника, ликвидатором должника, членом ликвидационной комиссии;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"p4_2_uchastnik","label":"Презумпция: ≥50% акций, >½ долей или назначение руководителя","text":"ответчик имел право самостоятельно либо совместно с заинтересованными лицами распоряжаться пятьюдесятью и более процентами голосующих акций (более чем половиной долей уставного капитала, более чем половиной голосов в общем собрании участников) либо право назначать (избирать) руководителя должника и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 2 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 2 п. 4 ст. 61.10 127-ФЗ","quote":"2) имело право самостоятельно либо совместно с заинтересованными лицами распоряжаться пятьюдесятью и более процентами голосующих акций акционерного общества, или более чем половиной долей уставного капитала общества с ограниченной (дополнительной) ответственностью, или более чем половиной голосов в общем собрании участников юридического лица либо имело право назначать (избирать) руководителя должника;","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"p4_3_vygoda","label":"Презумпция: выгода от недобросовестного поведения органов","text":"ответчик извлекал выгоду из незаконного или недобросовестного поведения лиц, указанных в п. 1 ст. 53.1 ГК РФ, и, пока не доказано иное, предполагается контролирующим должника лицом (пп. 3 п. 4 ст. 61.10 Закона о банкротстве)","norm":"пп. 3 п. 4 ст. 61.10 127-ФЗ","quote":"3) извлекало выгоду из незаконного или недобросовестного поведения лиц, указанных в пункте 1 статьи 53.1 Гражданского кодекса Российской Федерации.","source_url":"https://base.garant.ru/185181/03308cd8613911ed565ba834c260c64b/","group":"п. 4 ст. 61.10 — презумпции контроля"},{"value":"custom","label":"Свой вариант","text":"","norm":"","quote":"","source_url":"","group":""}],"id":"control_grounds_6110","allow_custom":true},"liability_grounds":{"label":"Основание ответственности КДЛ","multiple":true,"source":"documents/liability_grounds.json (Судебная практика)","edition_checked":"Гарант, действующая редакция на 16.10.2026; ПП ВС № 53 — с изм. ПП ВС от 23.12.2025 № 42","options":[{"value":"p61_11_1","label":"Невозможность погашения из-за действий (бездействия) КДЛ","text":"полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия ответчика как контролирующего должника лица (п. 1 ст. 61.11 Закона о банкротстве)","norm":"п. 1 ст. 61.11 127-ФЗ","quote":"Если полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия контролирующего должника лица, такое лицо несет субсидиарную ответственность по обязательствам должника.","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения"},{"value":"p61_11_2_1","label":"Презумпция: сделки, причинившие существенный вред","text":"кредиторам причинён существенный вред в результате совершения ответчиком или в его пользу либо одобрения им сделок должника (совершения сделок по его указанию), включая сделки по ст. 61.2 и 61.3 Закона о банкротстве; невозможность полного погашения требований презюмируется (пп. 1 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 1 п. 2 ст. 61.11 127-ФЗ","quote":"Пока не доказано иное, предполагается, что полное погашение требований кредиторов невозможно вследствие действий и (или) бездействия контролирующего должника лица при наличии хотя бы одного из следующих обстоятельств: 1) причинен существенный вред имущественным правам кредиторов в результате совершения этим лицом или в пользу этого лица либо одобрения этим лицом одной или нескольких сделок должника (совершения таких сделок по указанию этого лица), включая сделки, указанные в статьях 61.2 и 61.3 настоящего Федерального закона;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_11_2_2","label":"Презумпция: нет или искажены документы бухучёта","text":"документы бухгалтерского учёта и (или) отчётности к моменту введения наблюдения (признания должника банкротом) отсутствуют, не содержат обязательной информации либо она искажена, в результате чего существенно затруднено проведение процедур банкротства, в том числе формирование и реализация конкурсной массы (пп. 2 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 2 п. 2 ст. 61.11 127-ФЗ","quote":"2) документы бухгалтерского учета и (или) отчетности, обязанность по ведению (составлению) и хранению которых установлена законодательством Российской Федерации, к моменту вынесения определения о введении наблюдения (либо ко дню назначения временной администрации финансовой организации) или принятия решения о признании должника банкротом отсутствуют или не содержат информацию об объектах, предусмотренных законодательством Российской Федерации, формирование которой является обязательным в соответствии с законодательством Российской Федерации, либо указанная информация искажена, в результате чего существенно затруднено проведение процедур, применяемых в деле о банкротстве, в том числе формирование и реализация конкурсной массы;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","valid_until":"2027-07-26","valid_until_note":"подпункт изменён с 27.07.2027 Федеральным законом от 26.07.2026 № 253-ФЗ; будущая редакция не сверялась — вариант дан по действующей","parent":"p61_11_1"},{"value":"p61_11_2_3","label":"Презумпция: >50% реестра 3-й очереди — из правонарушений","text":"требования кредиторов третьей очереди по основной сумме задолженности, возникшие вследствие правонарушения, за которое должник или его единоличный исполнительный орган привлечён к уголовной, административной или налоговой ответственности, превышают 50% общего размера требований третьей очереди по основной сумме долга, включённых в реестр (пп. 3 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 3 п. 2 ст. 61.11 127-ФЗ","quote":"3) требования кредиторов третьей очереди по основной сумме задолженности, возникшие вследствие правонарушения, за совершение которого вступило в силу решение о привлечении должника или его должностных лиц, являющихся либо являвшихся его единоличными исполнительными органами, к уголовной, административной ответственности или ответственности за налоговые правонарушения, в том числе требования об уплате задолженности, выявленной в результате производства по делам о таких правонарушениях, превышают пятьдесят процентов общего размера требований кредиторов третьей очереди по основной сумме задолженности, включенных в реестр требований кредиторов;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_11_2_4","label":"Презумпция: нет или искажены корпоративные документы","text":"документы, хранение которых являлось обязательным по законодательству об АО, о рынке ценных бумаг, об инвестиционных фондах, об ООО, о ГУП и МУП, к моменту введения наблюдения (признания должника банкротом) отсутствуют либо искажены (пп. 4 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 4 п. 2 ст. 61.11 127-ФЗ","quote":"4) документы, хранение которых являлось обязательным в соответствии с законодательством Российской Федерации об акционерных обществах, о рынке ценных бумаг, об инвестиционных фондах, об обществах с ограниченной ответственностью, о государственных и муниципальных унитарных предприятиях и принятыми в соответствии с ним нормативными правовыми актами, к моменту вынесения определения о введении наблюдения (либо ко дню назначения временной администрации финансовой организации) или принятия решения о признании должника банкротом отсутствуют либо искажены;","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","valid_until":"2027-07-26","valid_until_note":"подпункт изменён с 27.07.2027 Федеральным законом от 26.07.2026 № 253-ФЗ; будущая редакция не сверялась — вариант дан по действующей","parent":"p61_11_1"},{"value":"p61_11_2_5","label":"Презумпция: нет или недостоверны сведения в ЕГРЮЛ/ЕФРСДЮЛ","text":"на дату возбуждения дела о банкротстве не внесены обязательные сведения либо внесены недостоверные сведения о должнике в ЕГРЮЛ и (или) в Единый федеральный реестр сведений о фактах деятельности юридических лиц (пп. 5 п. 2 ст. 61.11 Закона о банкротстве)","norm":"пп. 5 п. 2 ст. 61.11 127-ФЗ","quote":"5) на дату возбуждения дела о банкротстве не внесены подлежащие обязательному внесению в соответствии с федеральным законом сведения либо внесены недостоверные сведения о юридическом лице: в единый государственный реестр юридических лиц на основании представленных таким юридическим лицом документов; в Единый федеральный реестр сведений о фактах деятельности юридических лиц в части сведений, обязанность по внесению которых возложена на юридическое лицо.","source_url":"https://base.garant.ru/185181/2ad2cd3366f72a86c3210a630073139a/","group":"ст. 61.11 — невозможность полного погашения","parent":"p61_11_1"},{"value":"p61_12","label":"Неподача (несвоевременная подача) заявления должника","text":"ответчик не исполнил обязанность по подаче заявления должника в арбитражный суд (созыву заседания или принятию решения об обращении) в случаях и в срок, установленные ст. 9 Закона о банкротстве; размер ответственности равен размеру обязательств должника, возникших после истечения срока по п. 2–4 ст. 9 и до возбуждения дела о банкротстве (п. 1, 2 ст. 61.12 Закона о банкротстве)","norm":"п. 1, 2 ст. 61.12 127-ФЗ","quote":"Неисполнение обязанности по подаче заявления должника в арбитражный суд (созыву заседания для принятия решения об обращении в арбитражный суд с заявлением должника или принятию такого решения) в случаях и в срок, которые установлены статьей 9 настоящего Федерального закона, влечет за собой субсидиарную ответственность лиц … Размер ответственности в соответствии с настоящим пунктом равен размеру обязательств должника (в том числе по обязательным платежам), возникших после истечения срока, предусмотренного пунктами 2 - 4 статьи 9 настоящего Федерального закона, и до возбуждения дела о банкротстве должника (возврата заявления уполномоченного органа о признания должника банкротом).","source_url":"https://base.garant.ru/185181/0d0ea8cc116ee92c002c9bfac3919095/","group":"ст. 61.12 — неподача заявления должника"},{"value":"custom","label":"Свой вариант","text":"","norm":"","quote":"","source_url":"","group":""}],"excluded_options":[{"value":"p61_13_ubytki","label":"Убытки от нарушения Закона о банкротстве","norm":"п. 1 ст. 61.13 127-ФЗ","link_template":"zayavlenie_ubytki","reason":"убытки по ст. 61.13 — отдельное требование (размер — доказанные убытки, не реестр); оформляется шаблоном zayavlenie_ubytki"}],"id":"liability_grounds","allow_custom":true},"poshlina_mode":{"label":"Государственная пошлина","options":[{"value":"paid","label":"Уплачена","text":"Уплачена, платёжное поручение прилагается","norm":"пп. 9 п. 1 ст. 333.21 НК РФ; п. 2 ч. 1 ст. 126 АПК РФ"},{"value":"deferral","label":"Отсрочка","text":"Заявлено ходатайство об отсрочке (ст. 333.41 НК)","norm":"ст. 333.41 НК РФ; ст. 102 АПК РФ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}],"id":"poshlina_mode","allow_custom":true},"agenda_inclusion":{"id":"agenda_inclusion","label":"Решение о включении дополнительного вопроса","allow_custom":true,"options":[{"value":"included","label":"Включить","text":"вопрос включён в повестку дня","norm":"абз. 11 п. 2 ст. 15 127-ФЗ"},{"value":"not_included","label":"Не включать","text":"вопрос не включён в повестку дня","norm":"абз. 11 п. 2 ст. 15 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}]},"majority_base":{"id":"majority_base","label":"База большинства","allow_custom":false,"default":"present","options":[{"value":"present","label":"от присутствующих, п. 1 ст. 15","text":"от числа голосов кредиторов, присутствующих на собрании","norm":"п. 1 ст. 15 127-ФЗ","base_field":"ГОЛОСОВ_ПРИСУТСТВУЕТ"},{"value":"registry","label":"от общего числа голосов по реестру","text":"от общего числа голосов кредиторов, включённых в реестр","norm":"","base_field":"ГОЛОСОВ_ПО_РЕЕСТРУ","label_template":"от общего числа голосов по реестру, {norm}","norm_template":"{norm}","chip_label":"от реестра","chip_template":"от реестра · {norm_short}","placeholders":["norm","norm_short"]}]},"vote_outcome":{"id":"vote_outcome","label":"Итог голосования","allow_custom":true,"options":[{"value":"adopted","label":"Принято","text":"решение принято","norm":"ст. 15 127-ФЗ"},{"value":"not_adopted","label":"Не принято","text":"решение не принято","norm":"ст. 15 127-ФЗ"},{"value":"custom","label":"Свой вариант","text":"","norm":""}]},"salutation":{"label":"Обращение к адресату","allow_custom":true,"options":[{"value":"m","label":"Уважаемый","text":"Уважаемый","norm":"ГОСТ Р 7.0.97-2025, п. 5.19"},{"value":"f","label":"Уважаемая","text":"Уважаемая","norm":"ГОСТ Р 7.0.97-2025, п. 5.19"},{"value":"custom","label":"Свой вариант","text":"","norm":""}]},"attachment_copies":{"id":"attachment_copies","label":"Количество экземпляров приложения","allow_custom":true,"default":"1","options":[{"value":"1","label":"1 экз.","text":"1","norm":"ГОСТ Р 7.0.97-2025, п. 5.19"},{"value":"2","label":"2 экз.","text":"2","norm":"ГОСТ Р 7.0.97-2025, п. 5.19"},{"value":"3","label":"3 экз.","text":"3","norm":"ГОСТ Р 7.0.97-2025, п. 5.19"},{"value":"custom","label":"Другое число","text":"","norm":""}]},"procedure_person":{"id":"procedure_person","label":"Процедура (гражданин, в том числе ИП)","allow_custom":false,"default":"realization_gr","options":[{"value":"restructuring_gr","label":"Реструктуризация долгов гражданина","text":"реструктуризация долгов гражданина","norm":"ст. 213.2, 213.11 127-ФЗ"},{"value":"realization_gr","label":"Реализация имущества гражданина","text":"реализация имущества гражданина","norm":"ст. 213.2, 213.24 127-ФЗ"}]},"sufficiency_basis":{"id":"sufficiency_basis","label":"Основа вывода о достаточности имущества","allow_custom":false,"default":"balance","options":[{"value":"balance","label":"по балансу","text":"исходя из балансовой стоимости имущества, которое может быть реализовано для расчётов с кредиторами (пп. «в» п. 16 Приложения № 3 к Правилам, утв. постановлением Правительства РФ от 25.06.2003 № 367)","norm":"пп. «в» п. 16 Приложения № 3 к Правилам проведения арбитражным управляющим финансового анализа, утв. постановлением Правительства РФ от 25.06.2003 № 367"},{"value":"appraisal_ref","label":"по справочной оценке","text":"исходя из предполагаемой стоимости реализации имущества по данным справочной оценки на {{ДАТА_СПРАВОЧНОЙ_ОЦЕНКИ}}, не являющейся отчётом об оценке","norm":"","fields":["ДАТА_СПРАВОЧНОЙ_ОЦЕНКИ"],"reference_only":true,"note":"справочная оценка Оценщика Arbitr (не отчёт по 135-ФЗ); в документ печатается только дата оценки, сумма — никогда"}]}};
window.ARB_DOCS["vyvod_autofill"]={"note":"v1.7o, справочно: правила согласованы в группе, реализует Сисадмин в своём конфиге. Шаги каждого поля проверяются по порядку, срабатывает первый подходящий. then = значение варианта (value из choice_set) — только предлагается с подписью «из финанализа», ручная правка не перезаписывается; then = empty — поле пустое, под ним серая строка autofill_reasons[reason]. Отсутствующий ключ = условие для предложения не выполнено. v1.7p: у каждого шага when — машиночитаемые условия (массив, все должны выполняться — И; [] = всегда, только у шага «иначе»); текстовое условие осталось в if (по нему клиент узнаёт шаг «иначе»). Семантика — ops/combinators/key_syntax/resolve/derived; эталон — _eval_autofill в build_templates.py, проверка — fixtures и op_fixtures. v1.7q: fixtures/op_fixtures — в tests/vyvod_autofill_fixtures.json (fixtures_ref.path/sha256/count/op_count); is_iso_date; sdelki_no_bd/prednam_no_bd ловят не-ISO дату как no_bankruptcy_date; suff_appraisal_incomplete + autofill_reasons.appraisal_incomplete (text_template, action Дооценить).","debtor_type_unknown":"legal","keys":{"debtor_type":"legal / person (новый ключ; нет — legal)","applicant":"debtor / creditor / fns / other — кто подал заявление о банкротстве (новый ключ)","bankruptcy_date_source":"case — дата принятия заявления из карточки дела (новый ключ)","p855.nonmarket_deals[]":"сделки на нерыночных условиях по ПП № 855 (новый ключ, будущее)","assets_liquid":"стоимость имущества, которое можно реализовать (новый ключ финанализа)","expenses_estimate":"оценка расходов на процедуру = судебные расходы + вознаграждение АУ (ст. 20.6 127-ФЗ); вводит АУ в приложении","period":"[начало, конец] выписок","summary.high / summary.flagged":"число операций высокого уровня / с признаками","operations[].level":"high / medium / low","financial_state.years / ratios / conclusion":"годы отчётности, коэффициенты по годам, текстовый вывод"},"settings":{"fiktivnoe_ratio_threshold":{"value":1,"label":"по практике","ratios":["Коэффициент текущей ликвидности","Показатель обеспеченности обязательств активами"],"note":"в ПП № 855 числового порога нет (критерий п. 11 — возможность удовлетворить требования кредиторов в полном объёме); 1 — настройка, можно изменить"}},"fields":{"ВЫВОД_СДЕЛКИ":{"choice_set":"conclusion_sdelki","debtor_types":["legal","person"],"steps":[{"id":"sdelki_exist","if":"summary.high > 0","then":"exist","hint":"признаки — основание для проверки, а не доказательство недействительности сделки","when":[{"key":"summary.high","op":">","value":0}]},{"id":"sdelki_no_tx","if":"tx_count не задан или tx_count == 0","then":"empty","reason":"no_transactions","when":[{"not":{"key":"tx_count","op":">","value":0}}]},{"id":"sdelki_flagged","if":"summary.flagged > 0","then":"empty","reason":"flagged_operations","when":[{"not":{"key":"summary.flagged","op":"<=","value":0}}]},{"id":"sdelki_balance_flags","if":"balance_flags не пуст","then":"empty","reason":"balance_flags","when":[{"any":[{"key":"balance_flags","op":"missing"},{"key":"balance_flags","op":"not_empty"}]}]},{"id":"sdelki_unchecked","if":"unchecked_counterparties не пуст","then":"empty","reason":"unchecked_counterparties","when":[{"any":[{"key":"unchecked_counterparties","op":"missing"},{"key":"unchecked_counterparties","op":"not_empty"}]}]},{"id":"sdelki_no_period","if":"period не задан","then":"empty","reason":"no_period","when":[{"key":"period.0","op":"empty"}]},{"id":"sdelki_no_bd","if":"bankruptcy_date не задана или не в формате ГГГГ-ММ-ДД","then":"empty","reason":"no_bankruptcy_date","when":[{"not":{"key":"bankruptcy_date","op":"is_iso_date"}}]},{"id":"sdelki_period_short","if":"period[0] > bankruptcy_date − 3 года (п. 3 ст. 192 ГК РФ)","then":"empty","reason":"period_short_3y","when":[{"not":{"key":"period.0","op":"date_before_minus_years","ref":"bankruptcy_date","years":3}}]},{"id":"sdelki_bd_source","if":"bankruptcy_date_source != 'case'","then":"empty","reason":"bankruptcy_date_not_case","when":[{"not":{"key":"bankruptcy_date_source","op":"==","value":"case"}}]},{"id":"sdelki_absent","if":"иначе","then":"absent","when":[]}]},"ВЫВОД_ПРЕДНАМЕРЕННОЕ":{"choice_set":"conclusion_prednamerennoe","debtor_types":["legal","person"],"never_auto":["found","impossible"],"steps":[{"id":"prednam_nonmarket","if":"p855.nonmarket_deals не пуст","then":"empty","reason":"finding_manager_decides","future_then":"found","note":"будущее: когда ключ появится в финанализе — предлагать found; на текущих ключах found не предлагается","when":[{"key":"p855.nonmarket_deals","op":"not_empty"}]},{"id":"prednam_no_tx","if":"tx_count не задан или tx_count == 0","then":"empty","reason":"no_transactions","when":[{"not":{"key":"tx_count","op":">","value":0}}]},{"id":"prednam_flagged","if":"summary.high > 0 или есть operations[].level = medium","then":"empty","reason":"flagged_operations","when":[{"any":[{"not":{"key":"summary.high","op":"<=","value":0}},{"key":"operations","op":"missing"},{"key":"operations","op":"any_eq","value":"medium","field":"level"}]}]},{"id":"prednam_balance_flags","if":"balance_flags не пуст","then":"empty","reason":"balance_flags","when":[{"any":[{"key":"balance_flags","op":"missing"},{"key":"balance_flags","op":"not_empty"}]}]},{"id":"prednam_no_period","if":"period не задан","then":"empty","reason":"no_period","when":[{"key":"period.0","op":"empty"}]},{"id":"prednam_no_bd","if":"bankruptcy_date не задана или не в формате ГГГГ-ММ-ДД","then":"empty","reason":"no_bankruptcy_date","when":[{"not":{"key":"bankruptcy_date","op":"is_iso_date"}}]},{"id":"prednam_period_short","if":"period[0] > bankruptcy_date − 2 года (п. 3 ст. 192 ГК РФ)","then":"empty","reason":"period_short_2y","when":[{"not":{"key":"period.0","op":"date_before_minus_years","ref":"bankruptcy_date","years":2}}]},{"id":"prednam_no_accounting","if":"debtor_type = legal и financial_state.years пуст","then":"empty","reason":"no_accounting","when":[{"key":"debtor_type_norm","op":"==","value":"legal"},{"key":"financial_state.years","op":"empty"}]},{"id":"prednam_not_found","if":"иначе","then":"not_found","when":[]}]},"ВЫВОД_ФИКТИВНОЕ":{"choice_set":"conclusion_fiktivnoe","debtor_types":["legal","person"],"never_auto":["found"],"steps":[{"id":"fikt_not_applicable","if":"applicant ∈ {creditor, fns, other} (любой тип должника)","then":"not_applicable","when":[{"key":"applicant","op":"in","value":["creditor","fns","other"]}]},{"id":"fikt_no_applicant","if":"applicant не задан или не из {debtor, creditor, fns, other}","then":"empty","reason":"no_applicant","when":[{"not":{"key":"applicant","op":"in","value":["debtor","creditor","fns","other"]}}]},{"id":"fikt_person","if":"debtor_type = person","then":"empty","reason":"person_manager_decides","when":[{"key":"debtor_type_norm","op":"==","value":"person"}]},{"id":"fikt_no_accounting","if":"financial_state.years пуст","then":"empty","reason":"no_accounting","when":[{"key":"financial_state.years","op":"empty"}]},{"id":"fikt_no_ratios","if":"за последний год financial_state.years нет «Коэффициент текущей ликвидности» или «Показатель обеспеченности обязательств активами»","then":"empty","reason":"no_ratios","when":[{"any":[{"not":{"key":"financial_state.ratios.<last_year>.Коэффициент текущей ликвидности","op":"is_number"}},{"not":{"key":"financial_state.ratios.<last_year>.Показатель обеспеченности обязательств активами","op":"is_number"}}]}]},{"id":"fikt_ratios_ok","if":"текущая ликвидность ≥ порога или обеспеченность обязательств активами ≥ порога (settings.fiktivnoe_ratio_threshold)","then":"empty","reason":"finding_manager_decides","when":[{"any":[{"not":{"key":"financial_state.ratios","op":"last_year_ratio_lt","name":"Коэффициент текущей ликвидности","value_setting":"fiktivnoe_ratio_threshold"}},{"not":{"key":"financial_state.ratios","op":"last_year_ratio_lt","name":"Показатель обеспеченности обязательств активами","value_setting":"fiktivnoe_ratio_threshold"}}]}]},{"id":"fikt_not_found","if":"иначе (legal, applicant = debtor, оба показателя < порога)","then":"not_found","when":[]}]},"ВЫВОД_ДОСТАТОЧНОСТЬ":{"choice_set":"conclusion_sufficiency","debtor_types":["legal","person"],"expenses_estimate":{"entered_by":"АУ в приложении","parts":["Судебные расходы","Вознаграждение АУ (ст. 20.6)"],"norm":"ст. 20.6, 59 127-ФЗ"},"steps":[{"id":"suff_appraisal_incomplete","if":"основа — справочная оценка (ctx.basis = appraisal_ref) и оценены не все позиции","then":"empty","reason":"appraisal_incomplete","when":[{"key":"basis","op":"==","value":"appraisal_ref"},{"any":[{"not":{"key":"appraisal_complete","op":"==","value":true}},{"not":{"key":"assets_liquid","op":"is_number"}}]}]},{"id":"suff_no_assets","if":"assets_liquid не задан","then":"empty","reason":"no_assets_liquid","when":[{"not":{"key":"assets_liquid","op":"is_number"}}]},{"id":"suff_no_expenses","if":"expenses_estimate не задана","then":"empty","reason":"no_expenses_estimate","when":[{"not":{"key":"expenses_estimate","op":"is_number"}}]},{"id":"suff_sufficient","if":"assets_liquid ≥ expenses_estimate","then":"sufficient","when":[{"key":"assets_liquid","op":">=","ref":"expenses_estimate"}]},{"id":"suff_insufficient","if":"иначе","then":"insufficient","when":[]}]},"ВЫВОД_ПЛАТЁЖЕСПОСОБНОСТЬ":{"kind":"text","debtor_types":["legal","person"],"steps":[{"id":"platezh_no_accounting","if":"financial_state.years пуст","then":"empty","reason":"no_accounting","when":[{"key":"financial_state.years","op":"empty"}]},{"id":"platezh_no_conclusion","if":"financial_state.conclusion пуст","then":"empty","reason":"no_conclusion","when":[{"key":"financial_state.conclusion","op":"empty"}]},{"id":"platezh_text","if":"иначе","then":"text","text_from":"financial_state.conclusion","when":[]}]}},"ui":{"source_label":"из финанализа","reason_placement":"inline_under_field","reason_style":"muted","reason_color":"grey"},"key_syntax":{"path":"ключ — путь через точку: summary.high, p855.nonmarket_deals; число — индекс массива (period.0); у словаря ключ сравнивается как строка","<last_year>":"подстановка: последний год из financial_state.years (годы приводятся к строке и сортируются, берётся последний); нет годов — ключ отсутствует","missing":"ключ отсутствует, если на пути нет такого поля/индекса или промежуточное значение не словарь/массив; значение null приравнивается к отсутствию"},"resolve":{"order":["derived","ctx_first","result","ctx"],"ctx_first":["expenses_estimate","assets_liquid"],"note":"первый сегмент ключа ищется: в derived (вычисляемые ключи) → для ключей из ctx_first — в ctx, если ключ там есть (даже null) → в result.json → в ctx (контекст приложения: карточка дела, ввод АУ). expenses_estimate вводит АУ в приложении. Основа достаточности — ctx.basis (balance | appraisal_ref), как в docs_concl.js. assets_liquid: при основе appraisal_ref приложение кладёт в ctx.assets_liquid сумму справочной оценки и ctx.appraisal_complete = true, а если оценены не все позиции — assets_liquid null и/или appraisal_complete false (шаг suff_appraisal_incomplete → appraisal_incomplete); при основе balance ctx.assets_liquid не передаётся и берётся result.json. ctx.settings.<имя> (число или {value}) переопределяет settings.<имя>.value."},"derived":{"debtor_type_norm":"debtor_type (result → ctx) в нижнем регистре: person/citizen/individual → person; legal → legal; отсутствует или любое другое значение → debtor_type_unknown (legal)"},"combinators":{"any":"{\"any\": [условия]} — ИЛИ: истинно, если выполнено хотя бы одно условие (непустой массив)","not":"{\"not\": условие} — отрицание; not от любого оператора на отсутствующем ключе даёт true (так выражено «нет данных → поле пустое»)"},"ops":{"_missing_key":"Общее правило: каждый оператор, кроме exists/missing/empty, на отсутствующем ключе (или null) возвращает false. Числа — number или строка-число («0.7»), bool не число; даты для сравнений — строка ГГГГ-ММ-ДД (см. is_iso_date).","exists":"ключ есть и значение не null","missing":"ключа нет или значение null","empty":"true для отсутствующего ключа, null, [], \"\" и строки из пробелов","not_empty":"ключ есть и значение не пусто (обратное empty); отсутствующий ключ → false","==":"значение равно value (строго: строка ≠ число, bool ≠ число)","!=":"значение есть и не равно value; отсутствующий ключ → false","in":"значение есть в списке value","not_in":"значение есть и его нет в списке value; отсутствующий ключ → false",">":"число > value (или > числа по ключу ref); не число или нет ключа/ref → false",">=":"число ≥ value (или ≥ числа по ключу ref); не число или нет ключа/ref → false","<":"число < value (или < числа по ключу ref); не число или нет ключа/ref → false","<=":"число ≤ value (или ≤ числа по ключу ref); не число или нет ключа/ref → false","is_number":"значение — конечное число или строка-число; отсутствующий ключ → false","any_eq":"значение — массив объектов, и у какого-нибудь элемента поле field равно value; не массив / нет ключа → false","none_in":"значение — массив объектов, и ни у одного элемента поле field не входит в список value (пустой массив → true); не массив / нет ключа → false","date_before_minus_years":"дата key ≤ дата ref минус years лет (29.02 → 28.02 в невисокосный год): {key: period.0, op, ref: bankruptcy_date, years: 3}; нет/не дата любой из двух → false","is_iso_date":"значение — строка ровно ГГГГ-ММ-ДД и существующий календарный день (2023-02-30 → false); отсутствующий ключ / null / иной формат → false","last_year_ratio_lt":"key — словарь коэффициентов по годам (financial_state.ratios); год — последний из financial_state.years; коэффициент name за этот год — число и < порога (value или settings[value_setting].value); чего-то нет → false"},"fixtures_ref":{"path":"tests/vyvod_autofill_fixtures.json","sha256":"17c1aa0f91e2420a85832fbed830e38e2cb38b4fd1958e239d18784183abdc4b","count":131,"op_count":63}};
